function group({width,offset,points}) {
  const buckets = new Map();
  for (const {t,n} of points) {
    const start = offset + Math.floor((t - offset) / width) * width;
    buckets.set(start, (buckets.get(start) || 0) + n);
  }
  return Array.from(buckets.entries()).sort((a, b) => a[0] - b[0]);
}

