function reserve({requested, lots}) {
  if (requested <= 0) return [];
  const sorted = lots
    .map((lot, index) => ({lot, index}))
    .sort((a, b) => {
      if (a.lot.expires !== b.lot.expires) return a.lot.expires - b.lot.expires;
      return a.index - b.index;
    });
  const result = [];
  let remaining = requested;
  for (const {lot} of sorted) {
    if (remaining <= 0) break;
    const take = Math.min(lot.units, remaining);
    if (take > 0) {
      result.push({id: lot.id, units: take});
      remaining -= take;
    }
  }
  return result;
}

