function freeSlots({start,end,bookings}) {
  const clipped = [];
  for (const b of bookings) {
    const s = Math.max(b[0], start);
    const e = Math.min(b[1], end);
    if (e > s) clipped.push([s, e]);
  }
  clipped.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const [s, e] of clipped) {
    if (merged.length && s <= merged[merged.length - 1][1]) {
      if (e > merged[merged.length - 1][1]) merged[merged.length - 1][1] = e;
    } else {
      merged.push([s, e]);
    }
  }
  const result = [];
  let cursor = start;
  for (const [s, e] of merged) {
    if (s > cursor) result.push([cursor, s]);
    if (e > cursor) cursor = e;
  }
  if (cursor < end) result.push([cursor, end]);
  return result;
}

